const input = $json || {};

const sampleItems = [
  {
    source: 'Meetup',
    title: 'Dubai Expats Rooftop Social',
    dateTime: '2026-08-08T20:00:00+04:00',
    endTime: '2026-08-08T23:00:00+04:00',
    venue: 'Palm Jumeirah, Dubai',
    url: 'https://www.meetup.com/example/events/123456789/',
    description: 'A rooftop social for international professionals and expats.',
    price: 80,
    currency: 'AED',
    attendeesCount: 42,
    groupName: 'Dubai Expats Social Club'
  },
  {
    source: 'Meetup',
    subject: 'Friday International Mixer',
    body: `Friday International Mixer
Date: 14 August 2026
Time: 7:30 PM - 10:30 PM
Venue: Dubai Marina
Price: AED 100
Meet new people in a relaxed international crowd.`,
    url: 'https://www.meetup.com/example/events/987654321/'
  }
];

let items = [];

if (Array.isArray(input.items)) {
  items = input.items;
} else if (Array.isArray(input.events)) {
  items = input.events;
} else if (Array.isArray(input.graphqlEvents)) {
  items = input.graphqlEvents;
} else if (Array.isArray(input.emails)) {
  items = input.emails;
} else if (Array.isArray(input.forwardedItems)) {
  items = input.forwardedItems;
} else if (Array.isArray(input.messages)) {
  items = input.messages;
} else {
  items = sampleItems;
}

return [{
  json: {
    request: input.request || {
      text: 'Meetup etkinliklerini getir',
      channel: 'manual_test',
      userId: 'savas'
    },
    items,
    metadata: {
      correlationId:
        input.metadata?.correlationId ||
        `meetup-${Date.now()}`,
      testMode:
        input.metadata?.testMode ?? true,
      apiMode:
        input.metadata?.apiMode || 'auto',
      sourceWorkflow:
        'Concierge OS - Meetup Connector',
      ...input.metadata
    }
  }
}];

const input = $json || {};
const items = Array.isArray(input.items) ? input.items : [];
const metadata = input.metadata || {};

const monthMap = {
  january: 0, february: 1, march: 2, april: 3,
  may: 4, june: 5, july: 6, august: 7,
  september: 8, october: 9, november: 10, december: 11
};

const normalizeSpace = value =>
  String(value || '').replace(/\s+/g, ' ').trim();

const parseDate = value => {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const parseTime = value => {
  const match = String(value || '').match(
    /(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?/i
  );

  if (!match) return { hour: 19, minute: 0 };

  let hour = Number(match[1]);
  const minute = Number(match[2] || 0);
  const meridiem = String(match[3] || '').toUpperCase();

  if (meridiem === 'PM' && hour < 12) hour += 12;
  if (meridiem === 'AM' && hour === 12) hour = 0;

  return { hour, minute };
};

const parseTextDate = text => {
  const compact = normalizeSpace(text);

  const isoMatch = compact.match(
    /(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{1,2}):(\d{2}))?/
  );

  if (isoMatch) {
    return new Date(
      `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}T${isoMatch[4] || '19'}:${isoMatch[5] || '00'}:00+04:00`
    );
  }

  const named = compact.match(
    /(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)?[,]?\s*(\d{1,2})\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s*(\d{4})?/i
  );

  if (!named) return null;

  const day = Number(named[1]);
  const month = monthMap[named[2].toLowerCase()];
  const year = Number(named[3] || new Date().getFullYear());

  const timeMatch = compact.match(
    /(?:Time:|at)\s*(\d{1,2}(?::\d{2})?\s*(?:AM|PM)?)/i
  );

  const time = parseTime(timeMatch ? timeMatch[1] : null);

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      time.hour - 4,
      time.minute
    )
  );
};

const parseEndFromRange = (text, start) => {
  if (!start) return null;

  const range = String(text || '').match(
    /(\d{1,2}(?::\d{2})?\s*(?:AM|PM)?)\s*[-–]\s*(\d{1,2}(?::\d{2})?\s*(?:AM|PM)?)/i
  );

  if (!range) {
    return new Date(start.getTime() + 3 * 60 * 60 * 1000);
  }

  const endTime = parseTime(range[2]);
  const end = new Date(start);
  end.setUTCHours(endTime.hour - 4, endTime.minute, 0, 0);

  if (end <= start) {
    end.setUTCDate(end.getUTCDate() + 1);
  }

  return end;
};

const extractUrl = item => {
  if (item.eventUrl) return item.eventUrl;
  if (item.url) return item.url;
  if (item.link) return item.link;

  const text =
    `${item.title || ''} ${item.subject || ''} ${item.body || ''} ${item.description || ''}`;

  const match = text.match(
    /https?:\/\/(?:www\.)?meetup\.com\/[^\s)>\]]+/i
  );

  return match ? match[0] : null;
};

const extractPrice = item => {
  if (item.price !== undefined && item.price !== null) {
    return Number(item.price);
  }

  const text =
    `${item.body || ''} ${item.description || ''}`;

  if (/\bfree\b/i.test(text)) return 0;

  const match =
    text.match(/AED\s*([0-9]+(?:\.[0-9]+)?)/i) ||
    text.match(/([0-9]+(?:\.[0-9]+)?)\s*AED/i);

  return match ? Number(match[1]) : null;
};

const extractLocation = item => {
  const direct =
    item.venue?.name ||
    item.venue?.address ||
    item.venue ||
    item.location ||
    item.city;

  if (direct) return normalizeSpace(direct);

  const text =
    `${item.body || ''}\n${item.description || ''}`;

  const labeled = text.match(
    /(?:Venue|Location|Place):\s*([^\n\r]+)/i
  );

  return labeled ? normalizeSpace(labeled[1]) : '';
};

const inferCategory = item => {
  const text = normalizeSpace(
    `${item.category || ''} ${item.title || ''} ${item.subject || ''} ${item.description || ''} ${item.body || ''}`
  ).toLowerCase();

  if (
    text.includes('singles') ||
    text.includes('dating') ||
    text.includes('speed dating')
  ) return 'dating';

  if (
    text.includes('party') ||
    text.includes('nightlife') ||
    text.includes('rooftop') ||
    text.includes('dj')
  ) return 'nightlife';

  if (
    text.includes('boxing') ||
    text.includes('fitness') ||
    text.includes('padel') ||
    text.includes('tennis')
  ) return 'fitness';

  if (
    text.includes('trip') ||
    text.includes('travel') ||
    text.includes('hiking')
  ) return 'travel';

  if (
    text.includes('cyber') ||
    text.includes('cloud') ||
    text.includes('career') ||
    text.includes('professional networking')
  ) return 'career';

  return 'social';
};

const events = [];
const rejected = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index] || {};

  const title = normalizeSpace(
    item.title ||
    item.name ||
    item.eventTitle ||
    item.subject ||
    ''
  );

  if (!title) {
    rejected.push({
      index,
      reason: 'missing_title',
      item
    });
    continue;
  }

  const combinedText =
    `${item.subject || ''}\n${item.body || ''}\n${item.description || ''}`;

  const start =
    parseDate(
      item.dateTime ||
      item.start ||
      item.startTime ||
      item.date
    ) ||
    parseTextDate(combinedText);

  if (!start) {
    rejected.push({
      index,
      title,
      reason: 'missing_or_invalid_start',
      item
    });
    continue;
  }

  const end =
    parseDate(item.endTime || item.end) ||
    parseEndFromRange(combinedText, start);

  const location = extractLocation(item);
  const sourceUrl = extractUrl(item);
  const estimatedCost = extractPrice(item);

  const attendeesCount = Number(
    item.attendeesCount ??
    item.going ??
    item.rsvpCount ??
    item.rsvps ??
    0
  );

  const groupName = normalizeSpace(
    item.groupName ||
    item.group?.name ||
    item.group ||
    ''
  );

  const description = normalizeSpace(
    item.description ||
    item.body ||
    item.snippet ||
    ''
  ).slice(0, 1500);

  const confidenceParts = [
    Boolean(title),
    Boolean(start),
    Boolean(location),
    Boolean(sourceUrl),
    Boolean(description)
  ];

  const confidence =
    confidenceParts.filter(Boolean).length /
    confidenceParts.length;

  events.push({
    id:
      item.id ||
      item.eventId ||
      `meetup-${Date.now()}-${index + 1}`,
    source: 'Meetup',
    platform: 'Meetup',
    title,
    start: start.toISOString(),
    end: end ? end.toISOString() : null,
    location,
    sourceUrl,
    estimatedCost,
    currency: item.currency || 'AED',
    category: inferCategory(item),
    description,
    confidence,
    metadata: {
      groupName,
      attendeesCount:
        Number.isFinite(attendeesCount)
          ? attendeesCount
          : null,
      originalItem: item,
      parsedAt: new Date().toISOString(),
      inputMode:
        item.dateTime || item.start
          ? 'structured_or_graphql'
          : 'email_or_forward'
    }
  });
}

return [{
  json: {
    success: true,
    result: {
      source: 'Meetup',
      apiEndpoint: 'https://api.meetup.com/gql-ext',
      inputItemCount: items.length,
      eventCount: events.length,
      events,
      rejectedItems: rejected
    },
    memoryUpdates: events.map(event => ({
      type: 'source_event',
      operation: 'append',
      payload: {
        id: event.id,
        source: event.source,
        title: event.title,
        start: event.start,
        location: event.location,
        sourceUrl: event.sourceUrl,
        status: 'collected',
        collectedAt: new Date().toISOString()
      }
    })),
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Meetup Connector',
      level: rejected.length ? 'warning' : 'info',
      correlationId:
        metadata.correlationId || '',
      message:
        `Parsed ${events.length} Meetup events from ${items.length} source items.`,
      details: {
        inputItemCount: items.length,
        eventCount: events.length,
        rejectedCount: rejected.length,
        apiMode: metadata.apiMode || 'auto'
      }
    }],
    nextAction: {
      type: 'merge_social_sources',
      targetWorkflow:
        'Concierge OS - Social Discovery Agent'
    },
    error: null
  }
}];
